<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
require dirname(__DIR__).'/webhook-inbox-support.php';
function snapshotSpec(int $body=32,int $maximum=1000,array $where=[]):array{return ['snapshot_test'=>['columns'=>['scope'=>'bytes:256','id'=>'int','body'=>'blob:'.$body,'password'=>'nullable_bytes:4096','tag'=>'bytes:64'],'primary'=>['scope','id'],'where'=>$where,'maximum_rows'=>$maximum]];}
function snapshotSource(PDO $pdo,int $body=32,int $maximum=1000,array $where=[]):SoSecurity\Account\SqlStateSnapshot{return new SoSecurity\Account\SqlStateSnapshot($pdo,'owned-profile',snapshotSpec($body,$maximum,$where),30000);}
function snapshotReason(string $reason,callable $op):void{++Check::$assertions;try{$op();}catch(SoSecurity\Exception\SecurityException $e){Check::same($reason,$e->reason());return;}throw new RuntimeException('Expected '.$reason);}
function snapshotInsert(PDO $pdo,string $scope,int $id,string $body='',?string $password=null,string $tag='owned'):void{$q=$pdo->prepare('INSERT INTO snapshot_test(scope,id,body,password,tag) VALUES(?,?,?,?,?)');$q->bindValue(1,$scope,PDO::PARAM_STR);$q->bindValue(2,$id,PDO::PARAM_INT);$q->bindValue(3,$body,PDO::PARAM_LOB);$q->bindValue(4,$password,$password===null?PDO::PARAM_NULL:PDO::PARAM_STR);$q->bindValue(5,$tag,PDO::PARAM_STR);try{$q->execute();}finally{$q->closeCursor();}}
function snapshotCase(bool $mysql,callable $body):void{
    $dir=privateDirectory();$socket=getenv('SOSECURITY_TEST_MYSQL_SOCKET');if($mysql&&(!is_string($socket)||!preg_match('~\A/tmp/sosecurity-mysql-[A-Za-z0-9_-]+/mysql\.sock\z~D',$socket)||!is_file(dirname($socket).'/account-test-owner')||is_link(dirname($socket)))){throw new RuntimeException('Owned local test MySQL only.');}
    $dsn=$mysql?'mysql:unix_socket='.$socket.';dbname=sosecurity_test;charset=utf8mb4':'sqlite:'.$dir.'/snapshot.sqlite';$options=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_TIMEOUT=>2];if($mysql){$options[PDO::ATTR_EMULATE_PREPARES]=false;}$pdo=new InboxTestConnection($dsn,$mysql?'sosecurity_test':null,$mysql?'integration-only':null,$options);$pdo->setAttribute(PDO::ATTR_STATEMENT_CLASS,[InboxTestStatement::class,[$pdo]]);$observer=new PDO($dsn,$mysql?'sosecurity_test':null,$mysql?'integration-only':null,$options);
    $pdo->exec('DROP TABLE IF EXISTS snapshot_test');$pdo->exec($mysql?'CREATE TABLE snapshot_test(scope VARBINARY(256) NOT NULL,id BIGINT UNSIGNED NOT NULL,body MEDIUMBLOB NOT NULL,password VARBINARY(4096) NULL,tag VARBINARY(64) NOT NULL,PRIMARY KEY(scope,id)) ENGINE=InnoDB':'CREATE TABLE snapshot_test(scope TEXT NOT NULL,id INTEGER NOT NULL,body BLOB NOT NULL,password TEXT NULL,tag TEXT NOT NULL,PRIMARY KEY(scope,id))');
    try{$body($pdo,$observer,$dir);}finally{$pdo->beforeStatement=null;$pdo->afterStatement=null;try{$pdo->exec('ROLLBACK');}catch(Throwable $e){}$pdo->exec('DROP TABLE IF EXISTS snapshot_test');$observer=null;$pdo=null;gc_collect_cycles();foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST) as $file){if($file->isDir()){rmdir($file->getPathname());}else{unlink($file->getPathname());}}rmdir($dir);}
}
